/* features.h */
extern _Atomic bool ff_new_checkout;

/* config.c: load once at start-up */
const char *v = getenv("FF_NEW_CHECKOUT");
atomic_store(&ff_new_checkout, v != NULL && strcmp(v, "1") == 0);

/* toggle point */
if (atomic_load(&ff_new_checkout)) {
    new_checkout(req);
} else {
    legacy_checkout(req);
}
